void reverse(int a[], int n) {
    int i, temp, unused;
    i = 0;
    while (i <= n / 2) {
        temp = a[i];
        a[i] = a[n - 1 - i];
        a[n - 1 - i] = temp;
        i = i + 1;
    }
    unused = 0;
}
